// ScreenDetector.js
// Operator control panel: start/stop screen detection + mode controls

const SYSTEM_MODULES = [
  { name: 'AI Detection Engine',  key: 'ai',     alwaysOn: false },
  { name: 'Plate Recognition',    key: 'ocr',    alwaysOn: false },
  { name: 'Alert System',         key: 'alert',  alwaysOn: true  },
  { name: 'Recording Module',     key: 'rec',    alwaysOn: false },
  { name: 'Database Sync',        key: 'db',     alwaysOn: true  },
  { name: 'Camera Health Check',  key: 'cam',    alwaysOn: true  },
];

function ModuleRow({ name, active }) {
  return (
    <div style={{
      display: 'flex',
      alignItems: 'center',
      gap: 8,
      padding: '6px 10px',
      borderRadius: 6,
      background: 'rgba(0,0,0,0.18)',
      border: '1px solid var(--border)',
    }}>
      <span
        className={`dot ${active ? 'dot-green dot-pulse' : 'dot-gray'}`}
        style={{ flexShrink: 0 }}
      />
      <span style={{
        fontFamily: 'var(--font-body)',
        fontSize: 11,
        color: active ? 'var(--text-1)' : 'var(--text-3)',
        flex: 1,
      }}>
        {name}
      </span>
      <span style={{
        fontFamily: 'var(--font-mono)',
        fontSize: 8.5,
        letterSpacing: '1px',
        color: active ? 'var(--green)' : 'var(--text-4)',
      }}>
        {active ? 'ONLINE' : 'STANDBY'}
      </span>
    </div>
  );
}

export default function ScreenDetector({ isRunning, onStart, onStop }) {
  return (
    <div className="card">
      <div className="card-header">
        <span className="card-title">
          {/* Monitor icon */}
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
            <rect x="2" y="3" width="20" height="14" rx="2"/>
            <line x1="8" y1="21" x2="16" y2="21"/>
            <line x1="12" y1="17" x2="12" y2="21"/>
          </svg>
          Detection Control Panel
        </span>
        <span style={{
          fontFamily: 'var(--font-mono)',
          fontSize: 8.5,
          color: 'var(--text-3)',
          letterSpacing: '1.5px',
        }}>
          OPERATOR PANEL
        </span>
      </div>

      <div className="card-body">
        <div style={{ display: 'flex', gap: 10, alignItems: 'center', flexWrap: 'wrap', marginBottom: 16 }}>

          {/* Primary action button */}
          {!isRunning ? (
            <button className="btn btn-start" onClick={onStart}>
              <svg width="13" height="13" viewBox="0 0 24 24" fill="currentColor">
                <polygon points="5,3 19,12 5,21"/>
              </svg>
              Start Screen Detection
            </button>
          ) : (
            <button className="btn btn-stop" onClick={onStop}>
              <svg width="13" height="13" viewBox="0 0 24 24" fill="currentColor">
                <rect x="6" y="6" width="12" height="12" rx="1"/>
              </svg>
              Stop Detection
            </button>
          )}

          {/* Auxiliary buttons */}
          <button className="btn btn-ghost" disabled={!isRunning}>
            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/>
              <polyline points="7,10 12,15 17,10"/>
              <line x1="12" y1="15" x2="12" y2="3"/>
            </svg>
            Simpan Frame
          </button>

          <button className="btn btn-ghost" disabled={!isRunning}>
            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <circle cx="11" cy="11" r="8"/>
              <path d="m21 21-4.35-4.35"/>
            </svg>
            Analisis Manual
          </button>

          {/* Sensitivity indicator */}
          <div style={{ marginLeft: 'auto', display: 'flex', alignItems: 'center', gap: 8 }}>
            <div style={{
              padding: '7px 12px',
              borderRadius: 6,
              background: 'rgba(0,0,0,0.2)',
              border: '1px solid var(--border)',
              display: 'flex', alignItems: 'center', gap: 8,
            }}>
              <span style={{
                fontFamily: 'var(--font-display)',
                fontSize: 8,
                color: 'var(--text-3)',
                letterSpacing: '1.5px',
              }}>
                SENSITIVITY
              </span>
              <div style={{ display: 'flex', gap: 3 }}>
                {[1,2,3,4,5].map(n => (
                  <div key={n} style={{
                    width: 8, height: 14,
                    borderRadius: 2,
                    background: n <= 4 ? 'var(--accent)' : 'rgba(0,194,255,0.12)',
                    boxShadow: n <= 4 ? '0 0 5px rgba(0,194,255,0.4)' : 'none',
                  }}/>
                ))}
              </div>
            </div>

            <div style={{
              padding: '7px 12px',
              borderRadius: 6,
              background: 'rgba(0,0,0,0.2)',
              border: '1px solid var(--border)',
              fontFamily: 'var(--font-display)',
              fontSize: 8,
              color: 'var(--text-3)',
              letterSpacing: '1.5px',
            }}>
              MODE: <span style={{ color: 'var(--accent)' }}>AUTO</span>
            </div>
          </div>
        </div>

        {/* System module grid */}
        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(3, 1fr)',
          gap: 8,
        }}>
          {SYSTEM_MODULES.map(mod => (
            <ModuleRow
              key={mod.key}
              name={mod.name}
              active={mod.alwaysOn || isRunning}
            />
          ))}
        </div>

        {/* Resource meters */}
        <div style={{
          display: 'flex',
          gap: 10,
          marginTop: 14,
        }}>
          {[
            { label: 'CPU', pct: 44,                       color: 'var(--accent)' },
            { label: 'GPU', pct: isRunning ? 79 : 12,      color: 'var(--green)' },
            { label: 'RAM', pct: 61,                       color: 'var(--orange)' },
            { label: 'NET', pct: isRunning ? 38 : 5,       color: 'var(--cyan)' },
          ].map(r => (
            <div key={r.label} style={{ flex: 1 }}>
              <div style={{
                display: 'flex', justifyContent: 'space-between', marginBottom: 4,
                fontFamily: 'var(--font-mono)', fontSize: 8.5,
                color: 'var(--text-3)', letterSpacing: '1px',
              }}>
                <span>{r.label}</span>
                <span style={{ color: r.color }}>{r.pct}%</span>
              </div>
              <div style={{
                height: 4, background: 'rgba(255,255,255,0.05)',
                borderRadius: 2, overflow: 'hidden',
                border: '1px solid var(--border)',
              }}>
                <div style={{
                  width: `${r.pct}%`, height: '100%',
                  background: r.color,
                  boxShadow: `0 0 6px ${r.color}`,
                  borderRadius: 2,
                  transition: 'width 1s ease',
                }}/>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
